SELECT r.id FROM branch_analysis_results r WHERE r.status='PROVEN_UNREACHABLE' AND NOT EXISTS (SELECT 1 FROM proof_records p WHERE p.id=r.proof_id AND p.verdict='ACCEPTED' AND p.verification_level='MODEL_UNREACHABLE' AND p.residual_frontier=0 AND p.ir_outcome_id=r.ir_outcome_id AND p.analysis_run_id=r.analysis_run_id AND EXISTS (SELECT 1 FROM analysis_runs a WHERE a.id=r.analysis_run_id AND a.status='COMPLETED' AND a.exploration_closed=1 AND a.cut_count=0));
